$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';$root='C:\JudasValidation';$base='http://192.168.122.1:8872';$out="$root\M78ContinuationResults";$owned="$out\combined-v2";$name='m78-combined-v2-balance-raw-outputs'
try{$rows=@();$paths=@();foreach($dir in @('balance-step-llvmpipe','balance-cold-step','balance-cold-stand','balance-cold-recovery')){foreach($file in Get-ChildItem -LiteralPath "$owned\$dir" -Recurse -File){if($file.FullName.Contains('\project\')){continue};$rel=$file.FullName.Substring($owned.Length+1);$rows+=@{path=$rel;bytes=$file.Length;sha256=(Get-FileHash $file.FullName).Hash.ToLower()};$paths+=$file.FullName}}
 $dest="$out\$name";if(Test-Path $dest){throw 'Preserve prior raw transfer'};New-Item -ItemType Directory $dest|Out-Null;foreach($row in $rows){$path=Join-Path $dest $row.path;New-Item -ItemType Directory ([IO.Path]::GetDirectoryName($path)) -Force|Out-Null;Copy-Item -LiteralPath (Join-Path $owned $row.path) -Destination $path};$z="$out\$name.zip";Compress-Archive -LiteralPath $dest -DestinationPath $z;if((Get-Item $z).Length -gt 16MB){throw 'Raw transfer exceeds bound'};@{scope='Exact saved failure and successful cold-pair raw artifacts; authored project fixture copies excluded';files=$rows;archiveSHA256=(Get-FileHash $z).Hash.ToLower();archiveBytes=(Get-Item $z).Length}|ConvertTo-Json -Depth 5|Set-Content "$out\$name.json" -Encoding UTF8;Invoke-WebRequest -UseBasicParsing "$base/$name.zip" -Method Post -InFile $z|Out-Null;Invoke-WebRequest -UseBasicParsing "$base/$name.json" -Method Post -InFile "$out\$name.json"|Out-Null
}catch{$p="$out\$name-error.txt";[string]$_.Exception.Message|Set-Content $p;Invoke-WebRequest -UseBasicParsing "$base/$name-error.txt" -Method Post -InFile $p|Out-Null;exit 1}
